pnpm --filter "@ai-sdk/harness..." build
cd examples/harness-e2e-tui
node --input-type=module -e "console.log(import.meta.resolve('@ai-sdk/harness/agent'))"
node --input-type=module < "$REPRO"  # REPRO: the script's path outside the checkout
